// Search Wikipedia using n8n helpers
// Handle both string and JSON input from the agent
let searchTerm = query;
if (typeof query === 'object') {
  searchTerm = query.query || query.some_input || query.input || Object.values(query)[0] || '';
} else if (typeof query === 'string') {
  try { const parsed = JSON.parse(query); searchTerm = parsed.query || parsed.some_input || parsed.input || query; } catch(e) {}
}

const baseUrl = 'https://en.wikipedia.org/w/api.php';
const ua = 'n8n-Agent-Demo/1.0 (sorbonne-m2-course)';

const searchData = await helpers.httpRequest({
  method: 'GET',
  url: baseUrl,
  qs: {action: 'query', list: 'search', srsearch: String(searchTerm), format: 'json'},
  headers: {'User-Agent': ua},
  json: true
});

const title = searchData.query?.search?.[0]?.title;
if (!title) return 'No Wikipedia article found for: ' + searchTerm;

const pageData = await helpers.httpRequest({
  method: 'GET',
  url: baseUrl,
  qs: {action: 'query', prop: 'extracts', exintro: 'true', explaintext: 'true', titles: title, format: 'json', redirects: '1'},
  headers: {'User-Agent': ua},
  json: true
});

const pages = pageData.query?.pages || {};
const page = Object.values(pages)[0];
return `${page.title}: ${(page.extract || 'No content').slice(0, 3000)}`;
